#!/usr/bin/env python3
import json
import sys
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    models = []

    def extract(obj):
        if isinstance(obj, str):
            models.append(obj)
        elif isinstance(obj, list):
            for item in obj:
                extract(item)
        elif isinstance(obj, dict):
            # Common shapes:
            # {"models": ["model-a", "model-b"]}
            # {"models": [{"id": "model-a"}, {"name": "model-b"}]}
            if "models" in obj:
                extract(obj["models"])
            elif "data" in obj and isinstance(obj["data"], list):
                extract(obj["data"])
            else:
                # Single model object
                for key in ("id", "model", "name"):
                    if key in obj and isinstance(obj[key], str):
                        models.append(obj[key])
                        break

    extract(data)

    # Deduplicate while preserving order
    seen = set()
    unique = []
    for m in models:
        if m not in seen:
            seen.add(m)
            unique.append(m)

    return unique


def post_chat(payload, timeout=TIMEOUT_SECONDS):
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            return True, json.loads(raw), None
    except urllib.error.HTTPError as e:
        err_body = e.read().decode("utf-8", errors="replace")
        return False, None, f"HTTP {e.code}: {err_body}"
    except urllib.error.URLError as e:
        return False, None, f"URL error: {e.reason}"
    except Exception as e:
        return False, None, f"Error: {e}"


def temperature_unsupported(error_text):
    if not error_text:
        return False
    t = error_text.lower()
    return ("temperature" in t) and (
        "unsupported" in t
        or "not supported" in t
        or "unknown" in t
        or "invalid" in t
        or "not allowed" in t
    )


def extract_response_text(resp_json):
    # OpenAI-compatible format: choices[0].message.content
    try:
        content = resp_json["choices"][0]["message"]["content"]
        if isinstance(content, str):
            return content.strip()
        return str(content).strip()
    except Exception:
        return ""


def test_model(model_name):
    start = time.perf_counter()

    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
        "temperature": 0,
    }

    ok, data, err = post_chat(payload, timeout=TIMEOUT_SECONDS)

    # Retry without temperature if unsupported
    if (not ok) and temperature_unsupported(err):
        payload.pop("temperature", None)
        ok, data, err = post_chat(payload, timeout=TIMEOUT_SECONDS)

    latency = time.perf_counter() - start

    if ok:
        text = extract_response_text(data)
        # Pass criterion: exact one word "OK"
        passed = (text == "OK")
        status = "PASS" if passed else "FAIL"
        preview = text[:50] if text else "<empty response>"
    else:
        status = "FAIL"
        preview = (err or "Unknown error")[:50]

    return {
        "model": model_name,
        "status": status,
        "latency": latency,
        "response": preview.replace("\n", " "),
    }


def print_table(results):
    headers = ["Model", "Status", "Latency", "Response"]

    model_w = max(len(headers[0]), *(len(r["model"]) for r in results)) if results else len(headers[0])
    status_w = max(len(headers[1]), *(len(r["status"]) for r in results)) if results else len(headers[1])
    latency_w = len(headers[2])
    response_w = max(len(headers[3]), *(len(r["response"]) for r in results)) if results else len(headers[3])

    sep = f"+-{'-' * model_w}-+-{'-' * status_w}-+-{'-' * latency_w}-+-{'-' * response_w}-+"
    print(sep)
    print(
        f"| {headers[0].ljust(model_w)} | "
        f"{headers[1].ljust(status_w)} | "
        f"{headers[2].ljust(latency_w)} | "
        f"{headers[3].ljust(response_w)} |"
    )
    print(sep)

    for r in results:
        lat = f"{r['latency']:.3f}s"
        print(
            f"| {r['model'].ljust(model_w)} | "
            f"{r['status'].ljust(status_w)} | "
            f"{lat.ljust(latency_w)} | "
            f"{r['response'].ljust(response_w)} |"
        )
    print(sep)


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <models_config.json>")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        models = load_models(config_path)
    except Exception as e:
        print(f"Failed to read config file: {e}")
        sys.exit(1)

    if not models:
        print("No models found in config.")
        sys.exit(1)

    results = []
    for m in models:
        results.append(test_model(m))

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["status"] == "PASS")
    failed = total - working
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
